const PACKAGE={"id":"BFSdual_LF06_Lernpfad_LS6_4","ls":"6.4","title":"Lernpfadübung · LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","version":"1.0","source":"Fachbereiche/BFSdual/LF06/LS_6_4_Selbstbedienungsflaeche_gestalten.md"};
const COMP=[["Fachkompetenz","Ich gestalte eine Selbstbedienungsfläche. Ich begründe, wie der Kundenlauf, die Plätze für die Artikel und die Produktinformationen der Kundschaft helfen. Die Kundschaft soll die Ware selbst finden, vergleichen und auswählen können."],["Personalkompetenz","Ich prüfe, ob eine Person sich mit meinem Entwurf zurechtfindet, wenn sie die Aktionsfläche noch nicht kennt."],["Sozialkompetenz","Ich höre mir Rückmeldungen dazu an, wie gut andere sich zurechtfinden. Ich erkläre dem Team, was ich deshalb ändere."],["Methodenkompetenz","Ich trage meine Beobachtungen zu den Kundenwegen und die Produktdaten in den Lageplan ein."],["Medienkompetenz","Ich gestalte Orientierungsschilder und Produktinformationen so, dass die Kundschaft sie an der vorgesehenen Stelle gut lesen und verstehen kann."]];
const BANK=[{"title":"Was Sarah und Sebastian beobachten","scene":"Sarah Huber aus dem Marketing und Sebastian Wolf aus dem Außendienst besuchen die Bike Arena Oltmanns in Leer. Die Zubehörfläche für die Frühjahrsaktion wird vorbereitet.","ask":"Welche Aussagen treffen zu?","options":["Sarah möchte, dass Familien die Aktion früh bemerken.","Sebastian achtet darauf, ob die Kundschaft Platz zum Stehen und Vergleichen hat.","Sebastian plant eine feste Beratung an der Zubehörfläche für Samstag.","Sarah möchte, dass die Kundschaft erst in der Fahrradabteilung von der Aktion erfährt.","Die beiden prüfen, wie Sichtbarkeit und Bewegungsraum zusammenpassen.","Sarah und Sebastian wollen die Auswahl der Produkte erst nach der Aktion prüfen."],"answer":[0,1,4],"why":"Sarah achtet auf frühe Sichtbarkeit. Sebastian greift die Platzfrage auf. Am Samstag ist in der Aktion keine feste Beratung vorgesehen.","hint":"Sammle je eine Aussage von Sarah und Sebastian.","steps":"Ordne die Aussagen den Fragen nach dem ersten Blick und dem Platz beim Stehenbleiben zu.","example":"Ein günstig platzierter Hinweis hilft beim Finden. Der stehende Einkaufswagen braucht trotzdem Platz.","c":2,"sourceRefs":["Handlungssituation","M2"],"id":0,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Einen Einkauf aus Sicht der Kundschaft betrachten","scene":"Ein Vater und sein Sohn nehmen je eine Pumpe in die Hand. Sie suchen nach einem Modell für das Rad des Kindes. Der Vater stellt beide Pumpen zurück und geht weiter.","ask":"Welche Beobachtungen sollte dein eigener Entwurf bei der Probe aufgreifen?","options":["Der Vater sucht auf der Rückseite der Verpackung eine Angabe zur Ventilart.","Der Sohn findet die passende Pumpe mithilfe einer Preisaktion.","Der Wagen steht im Weg, sodass andere ausweichen müssen.","Der Vater stellt beide Pumpen zurück, ohne eine auszuwählen.","Die Familie nutzt einen Wegweiser zur Kasse als Ventilhinweis.","Eine Verkäuferin erklärt, warum beide Modelle passen."],"answer":[0,2,3],"why":"Die beobachtete Suche und das Zurücklegen zeigen, was dein Entwurf bei der Auswahl prüfen sollte. Im selben Test lässt sich beobachten, ob der Wagen anderen den Weg lässt.","hint":"Versetze dich in die Familie und in eine vorbeigehende Person.","steps":"Notiere, was im Fall beim Suchen, beim Stehenbleiben und bei der Auswahl geschieht.","example":"Das Zurückstellen eines Artikels ist beobachtbar. Die Motivation kann durch eine gezielte Frage geklärt werden.","c":1,"sourceRefs":["Handlungssituation","M2","M5"],"id":1,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was Selbstbedienung bedeutet","scene":"An der Aktionsfläche ist am Samstag keine feste Beratung eingeplant.","ask":"Woran erkennst du eine funktionierende Selbstbedienungsfläche?","options":["Der Weg zur Ware ist für Kundinnen und Kunden erkennbar.","Alle Informationen zur Eignung werden durch das Personal vorgelesen.","Die Kundschaft kann die passenden Artikel selbst vergleichen.","Die Kundschaft kann Ware selbst vom Warenplatz nehmen.","Das Personal muss die Ware nach jeder Produktfrage aus dem Lager holen.","Die Produkte stehen so, dass nur das Personal sie greifen kann."],"answer":[0,2,3],"why":"In der Selbstbedienung findet, vergleicht und greift die Kundschaft die Ware überwiegend selbst. Schilder, lesbare Produktangaben und nutzbare Bedienseiten unterstützen diese Schritte.","hint":"Denk an den Einkauf von der ersten Orientierung bis zum Griff ins Regal.","steps":"Prüfe, welche Schritte eine Kundin oder ein Kunde selbst erledigen kann.","example":"Ein Hinweis am Regal kann helfen, die Wahl zwischen zwei Pumpen selbst zu treffen.","c":0,"sourceRefs":["Handlungssituation","M5","M6"],"id":2,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Kundenlauf einzeichnen","scene":"Vom Zugang gehen einige Personen direkt zur Fahrradabteilung. Familien halten mit Wagen am Rand der Aktionsfläche an, um zu lesen.","ask":"Welche Einträge bilden diese Beobachtungen sinnvoll ab?","options":["Der Kundenlauf ist die Zeit zwischen Öffnung und Ladenschluss.","Ein Pfeil führt vom Zugang Richtung Fahrradabteilung.","Ein möglicher Lesepunkt am Rand der Aktion wird markiert.","Nur Kundschaft, die bereits gekauft hat, wird im Plan berücksichtigt.","Am Lesepunkt wird geprüft, ob dort ein Einkaufswagen den Weg verengt.","Die Fahrradabteilung wird mit dem Orientierungsschild gleichgesetzt."],"answer":[1,2,4],"why":"Der Kundenlauf beschreibt Bewegungen im Laden. Ein Pfeil zeigt die Laufrichtung, eine Markierung den beobachteten Halt. Zusammen helfen die beiden Einträge, mögliche Engstellen zu erkennen.","hint":"Suche nach dem tatsächlich beschriebenen Weg und der Stelle zum Lesen.","steps":"Zeichne Bewegung und Halt mit verschiedenen Zeichen ein.","example":"Eine Person, die stehen bleibt, beansprucht Platz an einer bestimmten Stelle auf dem Wegplan.","c":3,"sourceRefs":["M1","M2","M6"],"id":3,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Gondel, Bedienzone und Zugangsweg","scene":"In der Bike Arena stehen zwei drehbare Gondeln zur Verfügung. Ware steht auf beiden langen Seiten jeder Gondel.","ask":"Welche Aussagen stimmen?","options":["Eine Gondel ist ein frei im Raum stehendes Verkaufsregal.","Die Bedienzone ist der freie Streifen vor der Warenseite.","Der Schildfuß darf in der Bedienzone stehen, wenn die Ware sichtbar bleibt.","Es genügt, nur eine der beiden langen Seiten erreichbar zu halten.","Alle Bedienseiten müssen vom Hauptgang aus erreichbar sein.","Die Bedienzone bezeichnet das oberste Regalfach."],"answer":[0,1,4],"why":"Die Gondeln tragen Ware an beiden langen Seiten. Vor jeder Seite bleibt ein Freistreifen zum Sehen und Greifen. Die Kundschaft muss diese Flächen vom Hauptgang aus erreichen können.","hint":"Unterscheide das Möbelstück, den freien Streifen davor und den Weg dorthin.","steps":"Gehe gedanklich vom Hauptgang bis zum Griff ins Regal.","example":"Auch bei einem gut sichtbaren Regal kann ein Gegenstand den Zugang versperren.","c":0,"sourceRefs":["M1","M6"],"id":4,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Schild oder Produktkarte?","scene":"Die Kundschaft kommt vom Eingang oder aus der Fahrradabteilung und möchte eine Pumpe finden und auswählen.","ask":"Welche Informationen haben die passende Aufgabe?","options":["Das Wort „Autoventil“ auf der Pumpenkarte hilft, die Kompatibilität zu prüfen.","Eine Karte mit der Pumpenlänge ersetzt den Hinweis, wo die Aktionsfläche liegt.","Ein Schild „Fahrradzubehör“ mit Pfeil kann zur Aktionsfläche führen.","Ein Logo auf dem Schild enthält schon alle Angaben zum Pumpenvergleich.","Die Angabe zum Manometer auf der Pumpenkarte hilft beim Vergleich.","Die farbliche Markierung des Hauptgangs ist die Ventilinformation zur Minipumpe."],"answer":[0,2,4],"why":"Ein Orientierungsschild führt zur richtigen Fläche. Produktkarten am Warenplatz helfen beim Vergleich von Ventilart oder Ausstattung.","hint":"Unterscheide „Wo finde ich es?“ und „Was passt zu meinem Bedarf?“.","steps":"Ordne jede Information einer Frage zu. Prüfe, ob sie diese Frage beantwortet.","example":"„Pumpen →“ hilft bei der Suche. „Mit Druckanzeige“ hilft bei der Wahl im Regal.","c":4,"sourceRefs":["M1","M3","M5","M6"],"id":5,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Pumpen, eine Warengruppe","scene":"In der Aktion steht die Minipumpe P50. Ein Exemplar der Standpumpe P51 aus dem normalen Angebot darf für den Vergleich dazugestellt werden.","ask":"Welche Aussagen sind richtig?","options":["P50 hat eine Druckanzeige.","P50 und P51 bilden als Pumpen eine Warengruppe.","P51 hat ein Manometer.","Die Standpumpe darf auch auf der Gondel stehen.","P51 passt ausschließlich auf Autoventile.","P50 ist für unterwegs gedacht."],"answer":[1,2,3,5],"why":"Beide Pumpen gehören zu einer Warengruppe. P50 ist für unterwegs gedacht und hat keine Druckanzeige. P51 bringt ein Manometer mit und darf als Vergleichsartikel auf die Gondel.","hint":"Lies die beiden Pumpenzeilen in M3 getrennt.","steps":"Vergleiche Warengruppe, Einsatz und Ausstattung und prüfe die Aufstellregel in M1.","example":"Ein Vergleichsartikel kann aus dem normalen Angebot kommen und trotzdem bei der Auswahl helfen.","c":0,"sourceRefs":["M1","M3","M6"],"id":6,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was beim Flaschenhalter passen muss","scene":"Eine Kundin hat eine Flasche mit 74 mm Durchmesser. Sie sieht zwei freiliegende Gewinde am Rahmen. Ihr Abstand ist noch unbekannt.","ask":"Welche Aussagen helfen bei der Auswahl von F60?","options":["74 mm liegen bei der Flasche im vorgesehenen Bereich.","Der Flaschenhalter ist für Flaschen von genau 64 mm Durchmesser gedacht.","Zwei sichtbare Gewinde reichen als endgültiger Eignungsnachweis für die Montage.","Die Kundin muss am Rahmen den Gewindeabstand prüfen.","Die Schrauben liegen bei.","Der Durchmesser der Flasche gibt den Abstand der Rahmengewinde an."],"answer":[0,3,4],"why":"Die Flasche passt nach dem Durchmesser in den Bereich 72–75 mm. Für die Montage müssen die beiden passenden Gewinde am Fahrrad 64 mm Abstand haben. Schrauben sind bereits enthalten.","hint":"Betrachte Flasche und Fahrradrahmen getrennt.","steps":"Vergleiche den Flaschendurchmesser mit dem Bereich. Suche dann das eigene Maß für den Rahmen.","example":"Durchmesser und Abstand beschreiben zwei verschiedene Merkmale.","c":0,"sourceRefs":["M2","M3","M6"],"id":7,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Was im Grundriss frei bleibt","scene":"In M1 liegen der Hauptgang und der Durchgang zur Fahrradabteilung neben der geplanten Aktion. Warenträger und Schilder stehen auf der Aktionsfläche.","ask":"Welche Aussagen stimmen?","options":["Der Hauptgang ist nur an seiner schmalsten Stelle freizuhalten.","Der Hauptgang liegt zwischen y = 0,00 m und y = 1,50 m.","Der Durchgang zur Fahrradabteilung liegt im östlichen Streifen zwischen x = 6,40 m und x = 8,00 m.","Die Gondeln dürfen quer im Hauptgang stehen, wenn sie gut sichtbar sind.","Hauptgang und Durchgang zur Fahrradabteilung bleiben in voller Breite frei.","Die Aktionsfläche füllt sämtliche 8,00 m Breite oberhalb des Hauptgangs."],"answer":[1,2,4],"why":"Der Hauptgang verläuft von West nach Ost. Der östliche Streifen oberhalb davon führt zur Fahrradabteilung. Die Aktionsfläche liegt westlich neben diesem Streifen.","hint":"Suche in M1 nach y für den Hauptgang und nach x für den östlichen Durchgang.","steps":"Trenne die farblich markierbaren Rechtecke anhand ihrer Koordinaten.","example":"Zwei benachbarte Flächen können eine gemeinsame Grenze haben und verschiedene Funktionen erfüllen.","c":3,"sourceRefs":["M1"],"id":8,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Welche Karte hilft beim Vergleichen?","scene":"Die Pumpenverpackungen sehen ähnlich aus. Die Kundschaft braucht schnell erkennbare Angaben direkt an der Gondel.","ask":"Welche Merkmale machen die Karte hilfreich?","options":["Beide Pumpen haben dieselben Zeilen für Ventilarten, Einsatz und Druckanzeige.","Die eigentliche Ventilangabe steht nur hinten auf einer einzelnen Verpackung.","Die Karte ist dort befestigt, wo die Kundschaft die Pumpen greift und vergleicht.","Fachwörter werden bei Bedarf erklärt, etwa „Manometer = Druckanzeige“.","Für die Minipumpe wird eine Druckanzeige angegeben, damit die Karten gleich aussehen.","Die Karte enthält nur Bilder ohne Produktbezug."],"answer":[0,2,3],"why":"Gleiche Kategorien machen den Vergleich leicht. Die Angaben müssen stimmen und am Ort der Auswahl gut lesbar sein. Ein erklärtes Fachwort hilft beim Verstehen.","hint":"Überlege, welche Frage an der Gondel ohne Beratung geklärt werden muss.","steps":"Prüfe Lesbarkeit, Standort und fachliche Richtigkeit der Angaben.","example":"Zwei Spalten mit denselben Zeilen lassen Unterschiede auf einen Blick erkennen.","c":4,"sourceRefs":["M1","M3","M5"],"id":9,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Die eigene Planung mit fremden Augen prüfen","scene":"Dein Team kennt die Skizze sehr gut. Eine andere Person sieht die Fläche zum ersten Mal.","ask":"Welche Prüfungen helfen, die tatsächliche Orientierung einzuschätzen?","options":["Das Team erklärt der Testperson vorab alle Schilder und Wege.","Die Testperson sagt, wo ihr der erste Hinweis auffällt.","Die Testperson sucht zu Beginn ohne vorgelesene Wegbeschreibung.","Das Team wertet allein das eigene Wissen über die Produktplätze aus.","Ein zweiter Startpunkt aus der Fahrradabteilung wird ausprobiert.","Die Testperson wartet beim Regal auf Anweisungen, bevor sie die richtige Pumpe auswählt."],"answer":[1,2,4],"why":"Eine unvoreingenommene Testperson zeigt, was der Aufbau selbst vermittelt. Der erste bemerkte Hinweis und verschiedene Startpunkte machen den Beobachtungsbogen aussagekräftig.","hint":"Denk an eine Person, die eure Planung noch nie gesehen hat.","steps":"Gib ein Einkaufsziel vor und beobachte, wann ein Hinweis gefunden wird.","example":"Wenn der Testperson der Weg vorab erklärt wird, prüft sie vor allem, ob sie sich an die Erklärung erinnert.","c":1,"sourceRefs":["M2","M5"],"id":10,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Rückmeldung konkret nutzen","scene":"Eine Testperson berichtet: „Ich sehe die Pumpen. Beim Lesen weiß ich aber nicht, welche Angaben zu welcher Pumpe gehören.“","ask":"Welche Reaktionen passen zur Rückmeldung?","options":["Die Rückmeldung als Beobachtung im Team weitergeben.","Die Karte mit klaren Spalten für P50 und P51 beschriften und erneut testen.","Die Regalbeschriftung entfernen, damit alle Karten gleich leer sind.","Die Rückmeldung allein als Wunsch nach größerer Schrift zusammenfassen.","Nachfragen, bei welcher Zeile oder Spalte die Zuordnung schwierig war.","Die Pumpen in einen anderen Laden verlegen."],"answer":[0,1,4],"why":"Die geschilderte Schwierigkeit betrifft die Zuordnung. Eine Rückfrage nennt die konkrete Stelle. Klar beschriftete Spalten und ein Wiederholungstest machen die Änderung überprüfbar.","hint":"Achte darauf, welche Schwierigkeit genau genannt wurde.","steps":"Besprecht gemeinsam Ursache, passende Änderung und eine kurze Nachprobe.","example":"Eine gut lesbare Zahl bleibt mehrdeutig, wenn die Spaltenüberschrift fehlt.","c":2,"sourceRefs":["M3","M5"],"id":11,"l":1,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Maßstab für Fläche und Verkehrswege","scene":"Der Modellgrundriss ist 8,00 m breit und 5,00 m tief. Der Maßstab ist 1:25. Der Hauptgang ist 1,50 m breit.","ask":"Welche Maße stimmen auf dem Papier?","options":["Der ganze Bereich ist 32 cm × 20 cm groß.","Der ganze Bereich ist 20 cm × 12,5 cm groß.","Der Hauptgang ist 3,75 cm breit.","Der Hauptgang ist 6,0 cm breit.","Die 5,00 m Tiefe ergeben 25,0 cm.","1 cm auf dem Papier entspricht 25 cm im Laden."],"answer":[0,3,5],"why":"Rechne die wirklichen Maße in Zentimeter um und teile durch 25. 800 cm ergeben 32 cm, 500 cm ergeben 20 cm und 150 cm ergeben 6 cm.","hint":"Schreib 8,00 m, 5,00 m und 1,50 m zunächst als Zentimeter.","steps":"Teile jeden Wert durch 25. Vergleiche dann Hauptgang, Breite und Tiefe.","example":"2 cm auf dem Blatt entsprechen hier 50 cm im Laden.","c":3,"sourceRefs":["M1"],"id":12,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Bauteile im Gondelmodell","scene":"Eine Gondel misst 1,60 m × 0,60 m. Der Schildfuß misst 0,40 m × 0,40 m. Vor jeder langen Seite bleiben 1,20 m als Bedienzone frei. Das Modell hat den Maßstab 1:25.","ask":"Welche Maße brauchst du im Modell?","options":["Die Gondel misst 4,0 cm × 2,4 cm.","Der Schildfuß misst 1,6 cm × 1,6 cm.","Eine Bedienzone ist 4,8 cm breit.","Die Gondel misst 6,4 cm × 2,4 cm.","Eine Bedienzone ist 3,0 cm breit.","Der Schildfuß misst 4,0 cm × 4,0 cm."],"answer":[1,2,3],"why":"Gondel: 160 cm ÷ 25 = 6,4 cm und 60 cm ÷ 25 = 2,4 cm. Schildfuß: 40 cm ÷ 25 = 1,6 cm je Seite. Bedienzone: 120 cm ÷ 25 = 4,8 cm.","hint":"Setze für jedes Bauteil immer denselben Maßstab ein.","steps":"Rechne jede Seitenlänge einzeln um und ordne sie dem richtigen Bauteil zu.","example":"50 cm im Laden brauchen bei 1:25 im Modell 2 cm.","c":3,"sourceRefs":["M1","M4"],"id":13,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Möbel an der Grenze prüfen","scene":"Übungsvariante: Eine Gondel reicht von x = 5,10 m bis x = 6,70 m. Ihre gesamte y-Ausdehnung liegt oberhalb von y = 1,50 m. Ab x = 6,40 m beginnt dort der Durchgang zur Fahrradabteilung.","ask":"Welche Prüfergebnisse stimmen?","options":["Die Gondel ragt in den Hauptgang, weil sie westlich der Fahrradabteilung beginnt.","Die Gondel ragt 0,30 m in den Durchgang zur Fahrradabteilung.","Das Regal darf stehen bleiben, wenn ein Pfeil zur westlichen Bedienseite zeigt.","Der neue Standort muss den Durchgang und die erreichbaren Bedienseiten berücksichtigen.","Eine Drehung des Wegpfeils allein stellt die volle Gangbreite wieder her.","Die Koordinaten der Gondel sind mit der Begrenzung der Aktionsfläche vereinbar."],"answer":[1,3],"why":"Die rechte Kante liegt bei x = 6,70 m. Der Durchgang beginnt bei x = 6,40 m. Die Überlappung von 30 cm verletzt die Vorgabe. Nach einer Verschiebung ist auch die Erreichbarkeit erneut zu prüfen.","hint":"Vergleiche die rechte x-Grenze des Möbels mit x = 6,40 m.","steps":"Berechne die Überschneidung und unterscheide Möbel- und Bedienfläche.","example":"Die Position des Möbelkörpers ist zuerst zu prüfen, bevor du seine Bedienseite einzeichnest.","c":3,"sourceRefs":["M1"],"id":14,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Schildfuß vor dem Regal","scene":"Übungsvariante: Im Plan ist die Bedienzone 1,20 m breit. Der Schildfuß ragt an einer Stelle 0,20 m in diesen Streifen hinein.","ask":"Welche Feststellungen sind richtig?","options":["Die nutzbare Breite beträgt an dieser Stelle 1,00 m.","Die Zone erfüllt die Regel, weil sie auf dem Plan ursprünglich 1,20 m breit eingezeichnet war.","Der Schildfuß steht teilweise in einem Bereich, der für den Zugriff frei bleiben muss.","Das Schild sollte außerhalb der Bedienzone auf der Aktionsfläche platziert und auf Sichtbarkeit geprüft werden.","Wird der Schildtext deutlich größer, zählt der Schildfuß als Teil des freien Streifens.","0,20 m entsprechen 0,20 cm im Maßstab 1:25."],"answer":[0,2,3],"why":"Der Fuß verengt den Streifen an der Stelle auf 1,00 m. In der Bedienzone steht kein Schildfuß. Der richtige neue Standort ist sowohl an den Flächenregeln als auch an der Sichtbarkeit zu prüfen.","hint":"Suche die tatsächliche Engstelle am Boden.","steps":"Ziehe den belegten Teil von der Streifenbreite ab. Prüfe anschließend, wo der Fuß anders stehen kann.","example":"Ein am Regal befestigter kleiner Hinweis braucht keinen zusätzlichen Fuß auf dem Boden.","c":3,"sourceRefs":["M1","M5"],"id":15,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei kompatible Pumpen sinnvoll unterscheiden","scene":"Ein Vater braucht eine Pumpe für ein Autoventil. Er möchte sie in einer kleinen Tasche mitnehmen. Eine Druckanzeige braucht er nicht.","ask":"Welche Angaben und Folgerungen stimmen?","options":["Nur P51 passt laut Produktkarte zum Autoventil.","P50 und P51 passen laut Produktkarten zum Autoventil.","P50 ist mit 18 cm für den beschriebenen Einsatz unterwegs die naheliegende Wahl.","P50 muss wegen eines Manometers ausgewählt werden.","P51 ist laut Produktkarte 62 cm hoch und hat ein Manometer.","Die passende Ventilart entscheidet allein, welche Größe der Vater braucht."],"answer":[1,2,4],"why":"Beide Pumpenköpfe können am Autoventil genutzt werden. Für die kleine Tasche ist P50 mit 18 cm und ohne Druckanzeige die passendere Wahl. P51 ist größer und bietet eine Druckanzeige.","hint":"Kläre zuerst die Kompatibilität. Prüfe erst danach Größe und gewünschten Einsatz.","steps":"Vergleiche die beiden Produktkarten in denselben drei Kategorien.","example":"Wenn zwei Angebote zur selben Ventilart passen, hilft oft ein zweites Merkmal bei der Entscheidung.","c":0,"sourceRefs":["M2","M3"],"id":16,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine verlässliche Karte für F60","scene":"Die Produktkarte für F60 nennt geeignete Flaschen mit 72 bis 75 mm Durchmesser, zwei passende Rahmengewinde mit 64 mm Abstand und mitgelieferte Schrauben.","ask":"Welche Texte können auf einem kurzen, verlässlichen Schild stehen?","options":["„Die Flasche muss 64 mm Durchmesser haben.“","„Zwei passende Gewinde am Rahmen: Abstand 64 mm.“","„Mit Schrauben: passt an jede Stelle am Rahmen.“","„Für Flaschen mit 72–75 mm Durchmesser.“","„Schrauben liegen bei.“","„Zwei sichtbare Gewinde garantieren die Montage.“"],"answer":[1,3,4],"why":"Der Durchmesser beschreibt die passende Flasche. Der Abstand betrifft den Rahmen. Mitgelieferte Schrauben sind eine Zusatzangabe; die Kundschaft muss den Rahmen trotzdem prüfen.","hint":"Achte darauf, welches Maß zu welchem Gegenstand gehört.","steps":"Prüfe jeden Text am passenden Eintrag aus M3.","example":"Ein Schild kann eine Frage beantworten und zugleich zeigen, welche Messung am Rad noch fehlt.","c":4,"sourceRefs":["M2","M3","M5"],"id":17,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Weitere Artikel passend kennzeichnen","scene":"Neben den Pumpen und dem Flaschenhalter liegen L10, B80, S20 und T30 auf der Aktionsfläche.","ask":"Welche Angaben können unverändert auf das jeweilige Regalschild übernommen werden?","options":["L10: Die Halterung fürs Vorderlicht passt für Lenker mit 22 bis 32 mm Durchmesser.","B80: Das Klettband ist von 20 bis 40 cm Umfang verstellbar.","S20: Das Schloss gehört oben ins Regal, damit es am schnellsten sichtbar ist.","T30: Die Rahmentasche fasst 1,2 Liter und ist wasserabweisend.","B80: Das Band leuchtet ohne Beleuchtung selbstständig.","T30: Die Tasche ist vollständig wasserdicht."],"answer":[0,1,3],"why":"Die Maße für Lenker und Reflektorband sowie Volumen und Regenhinweis der Tasche entsprechen den Produktkarten. Das Schloss gehört nach M3 in die untere Regalzone. Das Band reflektiert auftreffendes Licht.","hint":"Schau je Aussage auf den Produktcode und den Wortlaut der Karte.","steps":"Prüfe Zahlen, Einheit und Produkteigenschaft. Achte besonders auf Wörter, die die Wirkung verstärken.","example":"Wasserabweisend und wasserdicht sind verschiedene Angaben.","c":0,"sourceRefs":["M3"],"id":18,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Zwei Startpunkte im Test abdecken","scene":"Übungsvariante: Eine Person beginnt den Einkauf am Zugang. Eine zweite kommt aus der Fahrradabteilung. Beide sollen Zubehör finden.","ask":"Welche Schritte liefern einen brauchbaren Vergleich der Orientierung?","options":["Beiden Personen vor dem Start die genaue Gondel zeigen.","Den Ort notieren, an dem jede Testperson den ersten Hinweis bemerkt.","Beide von ihrem vorgesehenen Startpunkt aus ohne Wegvorgabe suchen lassen.","Die zweite Person an der ersten starten lassen, damit beide immer denselben Laufweg haben.","Beide fragen, ob und wo sie das gewünschte Produkt gefunden haben.","Nur die bevorzugte Laufrichtung des Teams einzeichnen."],"answer":[1,2,4],"why":"Zwei verschiedene Ausgangspunkte zeigen, ob Hinweise aus beiden Richtungen wirken. Das Suchziel kann gleich bleiben. Beobachtung und Rückmeldung helfen, einen schwachen Hinweis zu finden.","hint":"Halte den Unterschied der Startpunkte im Test sichtbar.","steps":"Beobachte zuerst, wann ein Hinweis auffällt. Frage danach, wie die Person die Ware gefunden hat.","example":"Wer das Schild erst nach längerem Suchen entdeckt, liefert eine konkrete Stelle für die Überarbeitung.","c":2,"sourceRefs":["M2","M4","M5"],"id":19,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Messwerte und Einkaufsszene gemeinsam prüfen","scene":"Übungsvariante: Das Team hat die Bedienzonen im leeren Modell vermessen. Im Rollenspiel bleibt eine Person mit Wagen stehen und liest am Rand der Aktion.","ask":"Welche weiteren Prüfungen sind sinnvoll?","options":["Ausprobieren, ob eine zweite Person an ihr vorbei zur Fahrradabteilung kommt.","Die Prüfung abbrechen, weil die Maße im leeren Modell bereits eingetragen sind.","Beobachten, ob beide langen Gondelseiten erreichbar bleiben.","Die Zeit fürs Lesen als alleinigen Nachweis der Gangbreite verwenden.","Im Plan festhalten, wo Wagen und lesende Person während der Probe stehen.","Der Testperson vorschreiben, die Karte im Laufen zu lesen."],"answer":[0,2,4],"why":"Die Praxisprobe ergänzt die Messung. Sie zeigt, wo Menschen oder Wagen beim echten Einkauf Raum beanspruchen und ob andere Wege und Bedienseiten weiter erreichbar bleiben.","hint":"Prüfe, welche Bewegungen gleichzeitig stattfinden.","steps":"Markiere die Stelle des Halts und spiele die Bewegung einer zweiten Person nach.","example":"Eine Bedienzonenbreite auf Papier zeigt die Möblierung. Ein Rollenspiel zeigt zusätzlich das Verhalten.","c":1,"sourceRefs":["M2","M4","M5"],"id":20,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Gezielt nach einer Kartenrückmeldung handeln","scene":"Übungsvariante: Eine Testperson findet den Flaschenhalter und erkennt, dass er zu ihrer 74-mm-Flasche passt. Sie kann nach dem Lesen nicht sagen, was sie am Rad prüfen muss.","ask":"Welche Änderungen und Prüfungen greifen ihre Rückmeldung auf?","options":["Das Schild vom Halter entfernen, weil das Produkt schon gefunden wurde.","Auf der Karte Flaschendurchmesser und Abstand der Rahmengewinde in getrennten Zeilen zeigen.","Die Angabe „64 mm“ klar als Gewindeabstand am Fahrrad beschriften.","Das Team fragt bei einer zweiten Probe nach der Messung, die vor dem Kauf noch nötig ist.","Das Schild nur höher hängen und alle Zeilen unverändert lassen.","64 mm als Durchmesser der mitgebrachten Flasche ausweisen."],"answer":[1,2,3],"why":"Die Suche und der Flaschendurchmesser waren verständlich. Die Anpassung muss die Montagebedingung am Fahrrad hervorheben und mit einer ähnlichen Testfrage erneut geprüft werden.","hint":"Suche den Einkaufsschritt, den die Person bereits geschafft hat, und den, der noch offen ist.","steps":"Überarbeite die fehlende Zuordnung und prüfe, ob eine neue Testperson das nötige Maß nennen kann.","example":"Ein kleiner Test fragt etwa: „Welche Strecke würdest du am Fahrrad messen?“","c":2,"sourceRefs":["M2","M3","M5"],"id":21,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Einen zunächst überzeugenden Aufbau überprüfen","scene":"Übungsvariante: Du bevorzugst Plan A, weil das Schild gleich zu sehen ist. Dann bemerkst du, dass sein Fuß im Hauptgang steht. In Plan B bleibt der Weg frei, aus der Fahrradabteilung ist dessen Schild aber erst spät sichtbar.","ask":"Wie gehst du mit deiner ersten Einschätzung um?","options":["Bei A bleiben, weil die Kundschaft die Aktion früh sehen soll.","A an der Wegregel prüfen und die ursprüngliche Empfehlung bei belegter Überschneidung korrigieren.","Einen neuen Hinweis für B aus der Richtung der Fahrradabteilung testen lassen.","Am eigenen Entwurf beide Startpunkte ohne Wegerklärung prüfen lassen.","Die Prüfung beenden, sobald eine Testperson vom Eingang das Schild findet.","Den Schildfuß in A nur in einer anderen Farbe in den Plan zeichnen."],"answer":[1,2,3],"why":"Frühe Sichtbarkeit allein trägt die ursprüngliche Wahl nicht. Die Wegregel bestimmt, wo das Schild stehen darf. Beide Startpunkte im nächsten Test zeigen, ob die Hinweise auch ohne Erklärung auffallen.","hint":"Trenne deinen ersten Eindruck von der überprüfbaren Wegregel.","steps":"Vergleiche die beiden Ansätze nach freiem Weg und Sichtbarkeit. Lasse den überarbeiteten Entwurf ohne Hilfe testen.","example":"Beim Test darf eine Person ihren eigenen Weg wählen, damit du siehst, welcher Hinweis tatsächlich bemerkt wird.","c":1,"sourceRefs":["M1","M2","M5"],"id":22,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Eine Entscheidung im kurzen Pitch zeigen","scene":"Übungsvariante: Die Leitung möchte in ungefähr zwei Minuten verstehen, wie die Kundschaft nun eine Pumpe ohne feste Beratung auswählen kann.","ask":"Welche Elemente sind im Pitch passend?","options":["Im Lageplan vom Zugang zur Pumpen-Gondel führen.","Die Packungsfarben aufzählen und den Ventilhinweis übergehen.","An der Vergleichskarte zeigen, wo die Kundschaft die Ventiltypen erkennt.","Eine Beobachtung nennen, die geholfen hat, Schild oder Karte zu verändern.","Nur die Überschrift des Lageplans laut vorlesen.","Den Durchgang zur Fahrradabteilung aus der Erklärung entfernen, obwohl er im geplanten Kundenlauf wichtig ist."],"answer":[0,2,4],"why":"Der Pitch verbindet Orientierung, Auswahl und einen Beleg für die Entscheidung. Die Leitung sieht, wo jemand hingeht, welche Angabe dort hilft und was die Probe über den Aufbau gezeigt hat.","hint":"Denke an den konkreten Einkauf vom ersten Hinweis bis zur Wahl am Regal.","steps":"Wähle eine Stelle im Plan, eine Produktangabe und eine Beobachtung aus.","example":"„Die Testperson hat beim ersten Versuch am falschen Regal angehalten“ ist eine nutzbare Beobachtung.","c":4,"sourceRefs":["M2","M3","M5"],"id":23,"l":2,"type":"multi","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","criteria":"Eine oder mehrere Antworten sind richtig. Wähle alle zutreffenden Aussagen."},{"title":"Ersten Probelauf vorbereiten","scene":"Übungsvariante: Kurz vor der Aktion erlaubt die Ladenleitung einen letzten Test. Eine Einkaufsspur beginnt am Zugang und führt zu den Pumpen. Die andere beginnt in der Fahrradabteilung und führt zum Flaschenhalter. Es gibt keine feste Beratung an der Fläche.","ask":"Wie startest du die Prüfung?","options":["Ich zeichne beide erwarteten Laufwege ein und markiere, wo die Personen jeweils ihren ersten Hinweis finden sollten.","Ich bitte zwei Personen, ohne Hilfestellung je eine Einkaufsrolle zu übernehmen und ihren Eindruck anschließend zu schildern.","Ich halte zuerst die freien Gänge und Bedienseiten als Prüfvorgaben fest und bestimme, wer beim Test die Wege beobachtet.","Ich markiere im Modell je einen Messpunkt für die freie Wegbreite und einen Punkt zum Lesen und nutze beide im Testprotokoll.","Ich bespreche mit dem Team, welche Rückfragen die Rollen beim Vorbeigehen und am Regal stellen dürfen, ohne ihnen den Weg vorzugeben.","Ich lege für den Test fest, wo Wagen und Testmaterial bereitstehen und welche Gänge jederzeit frei sein müssen."],"consequences":["Deine markierten Wege machen es möglich, erwarteten und beobachteten ersten Hinweis zu vergleichen.","Die Rollen liefern nachvollziehbare Eindrücke von beiden Startpunkten.","Vorgaben und Zuständigkeiten sind vor Beginn geklärt.","Messung und Beobachtung bekommen feste Bezugspunkte im Plan.","Beide Teams können Rückmeldungen sammeln, ohne den Testpersonen die Auswahl vorwegzunehmen.","Die Testmittel und die freizuhaltenden Bereiche sind vor der Probe berücksichtigt."],"why":"Die Probe prüft zwei Einkaufsrichtungen und freie Wege. Wer eigenständig einkaufen soll, braucht Hinweise, die auch ohne Erklärung wirken.","hint":"Lege den Schwerpunkt fest, mit dem du die kommenden Beobachtungen weiterverfolgst.","steps":"Entscheide, ob dein erster Schritt Daten sichert, Rückmeldungen organisiert oder Bedingungen des Tests klärt.","example":"Ein markierter Suchpunkt lässt sich im Plan zu einer späteren Beobachtung zuordnen.","c":3,"sourceRefs":["M1","M2","M5"],"id":24,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":0,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen."},{"title":"Einen Hinweis aus zwei Richtungen prüfen","scene":"Vom Eingang aus sieht die Testperson das Orientierungsschild. Die zweite Person sieht es aus der Fahrradabteilung erst, als sie schon an der Aktion vorbeigegangen ist.","ask":"Wie setzt du die Arbeit fort?","options":["Ich zeichne in den Plan ein, wo beide Personen das Schild zuerst bemerkt haben, und vergleiche die Sichtlinien.","Ich frage die zweite Person, wann sie den Hinweis erwartet hat, und lasse sie einen neuen Vorschlag ohne Wegvorgabe ausprobieren.","Ich prüfe, wo ein zweiter, an der Gondel befestigter Hinweis zulässig ist und ohne neuen Schildfuß montiert werden kann.","Ich fotografiere oder skizziere beide Blickrichtungen und prüfe daran, welche Seite der Gondel einen Hinweis aufnehmen kann.","Ich hole Rückmeldung von je einer Person aus beiden Laufrichtungen ein und lasse das Team daraus die sinnvollste Ausrichtung vorschlagen.","Ich plane den Standortwechsel unter der Bedingung, dass Hauptgang und Durchgang in voller Breite frei bleiben, und bestimme den Zeitpunkt für die Nachkontrolle."],"consequences":["Im Plan ist die unterschiedliche Wirkung des Schildes direkt verortet.","Die Rückmeldung benennt das Problem aus Sicht der vorbeigehenden Person und fließt in die nächste Probe ein.","Die ergänzende Befestigung wahrt die frei zu haltenden Bodenflächen.","Der Vergleich der Blickrichtungen gibt dir eine fachliche Grundlage für die Platzierung.","Die Ausrichtung berücksichtigt beide Einkaufsrichtungen.","Der Standortwechsel bleibt an die Wegregeln und einen Prüfschritt gebunden."],"why":"Ein gut sichtbares Schild kann aus einer Richtung spät auffallen. Eine weitere Beschilderung muss Wege und Bedienzonen freihalten.","hint":"Schließe an die Grundlage an, die du für den Probelauf gewählt hast.","steps":"Prüfe einen neuen Hinweis aus beiden Richtungen.","example":"Ein freier Blick aus dem Zugang sagt noch nichts über den Rückweg aus der Fahrradabteilung.","c":2,"sourceRefs":["M1","M2","M5"],"id":25,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":1,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":24,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Pumpenvergleich verständlich machen","scene":"Die Person vom Eingang findet die Pumpen. Auf der bisherigen Karte übersieht sie, dass beide Pumpen zum Autoventil passen. Sie erkennt auch schwer, welche Pumpe eine Druckanzeige hat.","ask":"Wie verbesserst du die Karte mit deinem bisherigen Schwerpunkt?","options":["Ich vergleiche die Karte mit M3 und markiere in einer Tabelle getrennt, was bei Ventilart und Druckanzeige bei P50 und P51 steht.","Ich frage, an welcher Stelle die Person die Angaben erwartet, und lasse sie zwei Kartenentwürfe kommentieren.","Ich lege fest, dass die Karte direkt an der Pumpengondel lesbar angebracht wird und keine Halterung in die Bedienzone ragt.","Ich halte fest, welche Zeile in der Probe übersehen wurde, und prüfe anhand der Produktkarte die neuen, gleich aufgebauten Spalten.","Ich lasse zwei Personen anhand der überarbeiteten Karte die passende Pumpe für unterschiedliche Zwecke wählen und hole ihre Begründungen ein.","Ich vereinbare, wer beide Produktdaten kontrolliert und die geprüfte Karte an der vorgesehenen Seite befestigt."],"consequences":["Die neue Karte stützt sich auf die Produktdaten und zeigt die Gemeinsamkeit und den Unterschied klar.","Die Rückmeldungen helfen, die entscheidenden Zeilen an einem erwartbaren Ort anzuordnen.","Die Karte unterstützt die Auswahl direkt am Regal und lässt den Zugriff frei.","Die Überarbeitung reagiert auf einen belegten Lesefehler und lässt sich erneut überprüfen.","Du erfährst, ob verschiedene Einkaufsbedürfnisse mit derselben Karte verstanden werden.","Datenprüfung und Anbringung sind geklärt, bevor die Karte eingesetzt wird."],"why":"Beide Pumpen passen zum Autoventil. Die Standpumpe hat ein Manometer. Platzierung, Vergleichbarkeit und Datenrichtigkeit unterstützen die Wahl.","hint":"Greife den Schwerpunkt deiner bisherigen Schritte auf.","steps":"Ordne die Rückmeldung der fehlenden oder schlecht auffindbaren Kartenzeile zu.","example":"Eine gemeinsame Zeile „Ventile“ erleichtert den Vergleich zweier passender Modelle.","c":4,"sourceRefs":["M2","M3","M5"],"id":26,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":2,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":25,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Flaschenhalter selbstständig auswählen","scene":"Die Person aus der Fahrradabteilung findet F60. Ihre Flasche misst 74 mm. Beide Rahmengewinde sind sichtbar, ihr Abstand ist unbekannt. Die Testperson liest die Maßangaben auf eurer Karte.","ask":"Wie stellst du sicher, dass sie vor dem Kauf die richtige Prüfung vornimmt?","options":["Ich überprüfe beide Maßangaben anhand von M3 und zeige getrennt, welche Angabe bereits erfüllt ist und was offen bleibt.","Ich frage die Testperson, was sie an ihrer Flasche weiß und was sie am Fahrrad noch messen würde, und passe die Karte bei Bedarf an.","Ich lege fest, dass die beiden Anforderungen auf der Karte unabhängig voneinander gelesen werden können, und vereinbare vor dem Aufbau eine Prüfung der Beschriftung.","Ich notiere den im Test genannten Gewindeabstand und prüfe anhand der Produktkarte, ob die nötige Rahmenmessung erkannt wurde.","Ich lasse eine zweite Person die Karte lesen und danach in eigenen Worten erklären, wo sie Maß nehmen würde.","Ich halte als Freigabebedingung fest, dass ein Teammitglied die getrennt ausgewiesenen Angaben zur Flasche und Rahmenmontage prüft."],"consequences":["Die Karte trennt die belegte Flaschenpassung von der offenen Montagefrage.","Die Testperson macht klar, ob die Karte schon zum richtigen nächsten Handlungsschritt führt.","Die getrennte Darstellung und ihre Kontrolle sind vor dem Öffnen verbindlich vorgesehen.","Du kannst anhand der beobachteten Antwort prüfen, ob die Montagebedingung verstanden wurde.","Eine unabhängige Rückmeldung zeigt, ob der Montagehinweis auch ohne Vorkenntnisse verständlich ist.","Es ist klar, wer die Vergleichsangaben vor dem Einsatz überprüft."],"why":"74 mm liegen im erlaubten Bereich für die Flasche. Am Fahrrad müssen die zwei passenden Rahmengewinde 64 mm auseinanderliegen. Ihre Sichtbarkeit allein reicht für die Entscheidung noch nicht aus.","hint":"Frage nach Flaschendurchmesser und Rahmenabstand getrennt.","steps":"Kläre, welcher Vergleich bereits möglich ist und welche Messung noch fehlt.","example":"Eine Person kann die richtige Flasche vorzeigen und die Montagefrage erst zu Hause prüfen.","c":0,"sourceRefs":["M2","M3","M5"],"id":27,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":3,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":26,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Beim Lesen Raum für den Einkauf lassen","scene":"Nach der Anpassung werden Pumpen- und Flaschenhalterkarte gut gefunden. Während eine Person mit Wagen die Pumpe vergleicht, weicht eine zweite auf dem Weg zur Fahrradabteilung aus.","ask":"Was tust du vor der Freigabe?","options":["Ich markiere den Halt des Wagens und kontrolliere im Modell die nutzbare Durchgangsbreite an diesem Punkt.","Ich lasse beide Rollen beschreiben, wo das Lesen oder Vorbeigehen schwierig wurde, und probiere mit ihnen eine kleine Anpassung aus.","Ich suche einen Lesepunkt innerhalb der Aktionsfläche, bei dem der Hauptgang und die Bedienzonen frei bleiben können, und ordne einen neuen Probelauf an.","Ich dokumentiere die Beobachtung vor und nach einer veränderten Kartenposition und vergleiche die beiden Wege.","Ich lasse Testpersonen mit und ohne Wagen an der geänderten Stelle vergleichen und frage danach, was sich für sie verändert hat.","Ich entscheide nach den Flächenregeln, welche Schildpositionen infrage kommen, und bestimme, wer die Abstände beim Aufbau misst."],"consequences":["Die Engstelle wird im Plan überprüfbar.","Die Anpassung berücksichtigt sowohl das Lesen als auch das Vorbeigehen.","Freie Wege bleiben feste Bedingungen bei der Suche nach einer Alternative.","Ein kontrollierter Vergleich zeigt, ob die Änderung den beobachteten Konflikt tatsächlich löst.","Die Rückmeldungen prüfen die Nutzbarkeit für zwei unterschiedliche Einkaufsabläufe.","Jemand kann kontrollieren, ob der gewählte Standort in der wirklichen Fläche die Vorgaben einhält."],"why":"Selbstständige Auswahl braucht lesbare Angaben und Platz zum Stehen. Die Beobachtung aus dem Probelauf ergänzt die gemessenen Breiten.","hint":"Behalte deinen bisherigen Prüfweg bei und richte ihn auf die Stelle, an der jemand ausweicht.","steps":"Prüfe gleichzeitig Leseposition, Wagen und vorbeigehende Person.","example":"Eine verschobene Karte kann auch den Punkt verändern, an dem die Kundschaft anhält.","c":1,"sourceRefs":["M1","M2","M4","M5"],"id":28,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":4,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":27,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]},{"title":"Den Aufbau begründet übergeben","scene":"Die Leitung bittet nach dem Probelauf um den aktualisierten Flächenplan, die Schilder und die Vergleichskarten. Sie möchte auch wissen, was beim wirklichen Aufbau noch geprüft wird.","ask":"Wie stellst du deinen fertigen Arbeitsweg vor?","options":["Ich zeige zwei konkrete Beobachtungen, die zu geänderten Hinweisen oder Wegen geführt haben, und benenne eine offene Kontrolle vor Ort.","Ich zeige, wie Rückmeldungen aus beiden Einkaufsrollen in Aufbau und Karten eingeflossen sind, und vereinbare eine Rückmeldung nach der Aufbauprobe.","Ich übergebe einen beschrifteten Aufbauplan mit freien Flächen und lege fest, wer Wege, Abstände und Karten vor dem Start prüft.","Ich verknüpfe die markierte Engstelle mit meinem Vorher-Nachher-Vergleich und zeige, wie sich die Auswahl an den Karten im Probelauf überprüfen ließ.","Ich benenne, welche Rückmeldung zur Orientierung und welche zum Vergleichen geführt hat, und erkläre, wer die Umsetzung erneut ausprobieren soll.","Ich ordne die restlichen Arbeiten nach Aufbau, Kontrolle der Wege und Freigabe der Karten und markiere die Verantwortlichen im Plan."],"consequences":["Die Leitung kann prüfen, auf welche Beobachtungen sich deine Änderungen stützen.","Die Leitung sieht, welche Erfahrungen Betroffener in der Fassung berücksichtigt sind.","Die Übergabe macht die Bedingungen und Verantwortlichkeiten des echten Aufbaus sichtbar.","Dein Vergleich verbindet Flächenplan, Einkaufstest und fachliche Änderungen.","Die Rückmeldungen bleiben im Weiterarbeiten nutzbar und die erneute Probe ist konkret.","Der Aufbau kann mit klarer Reihenfolge und zugeordneten Prüfungen erfolgen."],"why":"Eine überzeugende Übergabe zeigt den Weg, die Vergleichsinformationen und den Nachweis der Verbesserung. Der wirkliche Aufbau bietet Gelegenheit für die letzte Kontrolle.","hint":"Schließe mit dem Schwerpunkt ab, den du bei der ersten Entscheidung gewählt hast.","steps":"Verknüpfe die Empfehlungen mit deinem Plan und einem überprüfbaren nächsten Schritt.","example":"Eine noch ausstehende Kontrolle gehört als offene Aufgabe erkennbar in die Übergabe.","c":4,"sourceRefs":["M1","M3","M5"],"id":29,"l":3,"type":"story","caseLabel":"LS 6.4 · Waren auf einer Selbstbedienungsfläche präsentieren","storyIndex":5,"logicMap":[0,1,2,0,1,2],"logicRoles":["Belegweg","Beteiligungsweg","Rahmenweg","Belegweg","Beteiligungsweg","Rahmenweg"],"criteria":"Wähle eine Handlung. Am Ende siehst du, wie deine sechs Entscheidungen zusammenpassen.","branchFrom":28,"branchText":["Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast.","Beziehe die Angaben, die du gerade geprüft hast, in deine nächste Entscheidung ein.","Berücksichtige, wessen Rückmeldung oder Sichtweise du gerade aufgenommen hast.","Beachte bei deiner nächsten Entscheidung die Vorgabe oder Grenze, die du gerade geklärt hast."]}];
